    /// A struct of enums
    public var mark: Mark
    public var marks: [Mark]
    /// Tables of an enum, which a vector's view reads
    public var steps: [StepFields]

    public init(
        level: Level,
        levels: [UInt8],
        direction: Direction,
        directions: [Int8],
        unit: Unit,
        units: [UInt16],
        change: Change,
        changes: [Int16],
        status: Status,
        statuses: [UInt32],
        sign: Sign,
        signs: [Int32],
        mask: Mask,
        masks: [UInt64],
        extent: Extent,
        extents: [Int64],
        word: Word,
        mark: Mark,
        marks: [Mark],
        steps: [StepFields]
    ) {
        self.level = level
        self.levels = levels
        self.direction = direction
        self.directions = directions
        self.unit = unit
        self.units = units
        self.change = change
        self.changes = changes
        self.status = status
        self.statuses = statuses
        self.sign = sign
        self.signs = signs
        self.mask = mask
        self.masks = masks
        self.extent = extent
        self.extents = extents
        self.word = word
        self.mark = mark
        self.marks = marks
        self.steps = steps
